    const events=(window.HVMatchCenter?.events(matchId)||[]).filter(row=>row.status==='confirmed'&&row.minute<=Number(input.minute)),sourceClock=window.HVMatchCenter?.clock?.(matchId),clockSnapshot=sourceClock&&Number(sourceClock.minute)===Number(input.minute)?{...clone(sourceClock),running:false,runningSince:null,runningSinceMs:null}:null;
    const row={clockSnapshot,clockMinuteManuallyConfirmed:!!sourceClock&&!clockSnapshot,id:uid('IN'),matchId,cupId:game.tournamentId,fixtureSnapshot:{home:game.home,away:game.away,homeTeamId:game.homeTeamId,awayTeamId:game.awayTeamId,date:game.date,time:game.time,venue:game.venue,field:game.field},type:input.type,status:'open',reason:text(input.reason),minute:Number(input.minute),homeScore:Number(input.homeScore),awayScore:Number(input.awayScore),possession:input.possession,restart:text(input.restart),lastKickoff:text(input.lastKickoff).slice(0,200),internalNote:text(input.internalNote),playersOnField:currentPlayers(game,events,Number(input.minute),clockSnapshot),cards:events.filter(event=>['yellow','second-yellow','red'].includes(event.type)),substitutions:events.filter(event=>event.type==='substitution'),events:clone(events),rulesVersion:window.HVCompetition?.rulesForMatch(game)?.version||1,createdAt:now(),createdBy:'Scheidsrechter',history:[{at:now(),by:'Scheidsrechter',action:'Volledige momentopname vastgelegd op minuut '+input.minute+'.'}]};
