      const regulation=rules(game),regular=(Number(regulation.halfMinutes)||45)*2,total=Math.max(Number(game.playingMinutes)||regular,regular+(current.minute>regular&&regulation.extraTime?(Number(regulation.extraHalfMinutes)||15)*2:0)),remainingMinutes=Math.max(0,total-current.minute);
      const overlay={status:'suspended',homeScore:current.homeScore,awayScore:current.awayScore,minute:current.minute,date:input.date,time:input.time,field:text(input.field)||game.field,remainingMinutes,duration:Math.max(10,remainingMinutes+10),reason:'Restant ingepland; hervatting wacht op scheidsrechter'};
      const candidate={...game,...overlay,status:'scheduled'};candidate.venue=fixtures.venueFor(candidate);const conflict=fixtures.conflictFor(candidate);if(conflict)return fail('Dit restant overlapt met '+label(conflict)+'.');
